import java.util.*;
import java.io.*;

public class Main {
    static final int MOD1 = 998244353;
    static final int MOD2 = 1000000007;
    static final int BASE = 1000000;

    static int n, total, answer;
    static int[] sumArr = new int[15];
    static List<Integer>[] buckets = new ArrayList[15];

    static {
        for (int i = 0; i < 15; i++) {
            buckets[i] = new ArrayList<>();
        }
    }

    static void generateSequences(int depth, int currentNumber) {
        if (depth == 7) return;
        total++;
        int val = ((total - currentNumber) % MOD1 + MOD1) % MOD1;
        buckets[depth].add(val);
        sumArr[depth] = (sumArr[depth] + val) % MOD2;
        for (int digit = 0; digit <= 9; digit++) {
            generateSequences(depth + 1, currentNumber * 10 + digit);
        }
    }

    static void processNumber(int x) {
        if (x > n) return;
        if (x * BASE + BASE - 1 <= n && x * BASE * 10 > n) {
            int currentTotal = total;
            for (int i = 0, multiplier = 1; i <= 6; i++, multiplier *= 10) {
                int size = buckets[i].size();
                int diffVal = ((currentTotal - x * multiplier) % MOD1 + MOD1) % MOD1;
                int target = (MOD1 - diffVal);
                int position = lowerBound(buckets[i], target);
                answer = (answer + (long)diffVal * size + sumArr[i]) % MOD2;
                answer = (answer - (long)MOD1 * (size - position) % MOD2 + MOD2) % MOD2;
                total += size;
            }
            return;
        }
        total++;
        answer = (answer + ((total - x) % MOD1 + MOD1) % MOD1) % MOD2;
        for (int digit = 0; digit <= 9; digit++) {
            processNumber(x * 10 + digit);
        }
    }

    static int lowerBound(List<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= target) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine());
        generateSequences(0, 0);
        for (int i = 0; i <= 7; i++) {
            Collections.sort(buckets[i]);
        }
        total = 0;
        answer = 0;
        for (int i = 1; i <= 9; i++) {
            processNumber(i);
        }
        System.out.println(answer);
    }
}
